/**
 * The compiled AUTISTIK Launch Pad v4 (holder rewards) and AUTISTIK Burner, used by the admin's one-click deploy and by the Hub to
 * predict token addresses. Launch Pad v4 is generated from contracts/AutistikLaunchpadV4.input.json with solc 0.8.24
 * (optimizer 200 runs, paris); the burner is the one already deployed on BNB Chain, unchanged. Don't edit by hand.
 */
export const PAD_COMPILER = "v0.8.24+commit.e11b9ed9";
export const PAD_BYTECODE = "" as const;
export const BURNER_BYTECODE = "" as const;
/** Launch Pad version PAD_BYTECODE deploys. */
export const PAD_VERSION = 4;
/** keccak256 of the AutistikToken creation code per Launch Pad version: with the deployer and a salt it gives a token's address (CREATE2). */
export const TOKEN_INIT_HASHES: Record<number, string> = {
  3: "0x5c40f6d3b62ec709f49f071b852d09a19b72ce4462b728f106b9208de613a666",
  4: "0xc6ffe6fb3eff93db6b6c0f6a2702235f7f28a1d2de3c81f5fb9e218199ae66ef",
};
export const tokenInitHash = (version: number) => TOKEN_INIT_HASHES[version] ?? TOKEN_INIT_HASHES[3];
